"""Generate Russian manuals from reviewed examples and actual public API declarations.
Run after API changes; missing component prose fails rather than creating an empty page.
"""
from pathlib import Path
import re
from manual_content import D
root=Path(__file__).resolve().parents[1]
out=root/'docs/manual';out.mkdir(exist_ok=True)
help={
'label':'Подпись элемента или доступное имя.','title':'Заголовок блока или окна.','value':'Текущее значение; тип и правила описаны выше.','valueexpression':'Выражение поля модели для валидации. @bind-Value создаёт автоматически; при ручных Value/ValueChanged передайте явно, даже вне формы.',
'valuechanged':'Новое значение для родителя; сохраните его в модели.','onchanged':'Новое значение для родителя; обновите состояние через setState.','items':'Исходные элементы. Тип модели указан в сигнатуре; заменяйте список при изменениях.',
'columns':'Описание колонок либо поле измерения; см. модель и пример.','disabled':'true запрещает действия пользователя.','enabled':'false запрещает действия пользователя.','required':'true требует непустое значение при проверке формы.','placeholder':'Подсказка внутри пустого поля.','id':'Уникальный HTML ID; по умолчанию генерируется.','min':'Нижняя включительная граница.','max':'Верхняя включительная граница.','step':'Шаг числового ввода.','childcontent':'Содержимое Razor-компонента.','child':'Дочерний Flutter-виджет.','actions':'Кнопки/действия окна.','primary':'Выделяет основное действие цветом темы.','type':'HTML-тип кнопки: button или submit.','onclick':'Событие нажатия.','onpressed':'Обработчик нажатия; null отключает Flutter-кнопку.','additionalattributes':'Дополнительные HTML/ARIA атрибуты; не используйте для обхода проверок модели.',
'controller':'Контроллер текста. Не совмещайте с initialValue; dispose выполняет владелец.','initialvalue':'Начальное значение, а не постоянно управляемое значение.','validator':'Проверка поля: null при успехе, строка с ошибкой при отказе.','rows':'Число видимых строк текстового поля.','maxlength':'Максимальная длина текста.','maxselected':'Ограничение количества выбранных ключей.','disableddate':'Функция возвращает true для запрещённого дня.','culture':'Культура подписей календаря.','firstdayofweek':'Первый день недели календаря.','model':'Объект данных для EditForm/DataAnnotations.','name':'Имя формы.','showsummary':'Показывать сводку ошибок.','onvalidsubmit':'Вызывается после успешной валидации; сохранение выполняет приложение.','oninvalidsubmit':'Вызывается при неуспешной проверке формы.','submitlabel':'Текст встроенной Flutter-кнопки отправки.','formkey':'Необязательный ключ для доступа к FormState.','selectedindex':'Индекс выбранной вкладки, начиная с 0.','selectedindexchanged':'Изменение выбранной вкладки.','open':'Открыто ли окно.','openchanged':'Сообщает родителю о закрытии/открытии.','visible':'Видимость уведомления.','visiblechanged':'Обновление видимости после закрытия.','tone':'Стиль уведомления, например success или error.','message':'Текст уведомления.','error':'true включает оформление ошибки.','ondismiss':'Запрос убрать уведомление.','text':'Текст подсказки либо функция подписи узла (смотрите тип).','total':'Число записей после фильтрации.','page':'Текущая страница, начиная с 1.','pagesize':'Положительное количество строк на странице.','sizes':'Доступные размеры страницы.','pagechanged':'Запрос изменить номер страницы.','onpagechanged':'Запрос изменить номер страницы.','pagesizechanged':'Запрос изменить размер страницы.','onpagesizechanged':'Изменение размера страницы; обычно также сбрасывают page в 1.','onnavigate':'ID выбранного предка.','rowid':'Функция уникального стабильного ключа записи.','emptytext':'Сообщение для пустого результата.','selectable':'Показывать выбор строк.','selectedids':'Набор выбранных ID.','selectedidschanged':'Новый набор выбранных ID.','onselectionchanged':'Новый набор выбранных ID.','toolbar':'Пользовательская панель действий.','rowactions':'Шаблон действий для конкретной записи.','initialpagesize':'Начальный размер страницы при создании компонента.','expandedids':'Набор раскрытых ID дерева.','expandedidschanged':'Новый набор раскрытых ID.','onexpandedchanged':'Новый набор раскрытых ID; сохраните его.','selectedid':'ID текущего узла либо null.','selectedidchanged':'Выбор другого узла.','onselected':'ID выбранного узла.','kind':'Режим диаграммы NgChartKind.','categories':'Подписи категорий в порядке значений.','series':'Набор NgChartSeries с равным категориям числом значений.','onpointselected':'Выбранная точка NgChartSelection.','unit':'Подпись единиц измерения.','date':'Любая дата отображаемой недели.','datechanged':'Новая дата после навигации недели.','ondatechanged':'Новая дата после навигации недели.','oncreate':'Выбранный день для создания события; откройте свой редактор.','onedit':'Выбранное событие для редактирования.','readonly':'Запрещает редактирование и историю, сохраняя просмотр.','rowfield':'Ключ строкового измерения в Dimensions/dimensions.','columnfield':'Ключ столбцового измерения.','aggregate':'Sum, Count, Average, Min или Max.','oncellselected':'Измерения и исходные записи выбранной ячейки/итога.'}
flutter={}
for p in (root/'packages/nextgen_components/lib/src').glob('*.dart'):
 s=p.read_text()
 for m in re.finditer(r'class (Ng\w+)(?:<[^\n]+>)? extends (?:StatefulWidget|StatelessWidget)',s):
  end=s.find('@override',m.end());flutter[m[1]]=(p,s[m.end():end])
def md(s):return s.replace('|','\\|').replace('\n',' ')
index=['# Руководство Nextgen Components','', 'Версия 0.8. Подробное руководство для всех публичных компонентов Blazor и Flutter Web. Это описание фактически реализованного API, а не обещание полного набора возможностей Telerik.','', 'Начните с [подключения и правил состояния](getting-started.md), затем выберите компонент. Модели и формулы описаны в [справочнике данных](models.md). Реальные ограничения и результаты проверок: [verification](../verification.md).','', 'Примеры Blazor — содержимое Razor-страницы с `@using NextgenComponents.Blazor`. Flutter-примеры — поля и методы внутри `State` после `import package:nextgen_components/nextgen_components.dart`; `build` возвращает отдельный компонент, оберните страницу в MaterialApp/Scaffold, как в начальном руководстве.','', '| Компонент | Назначение |','|---|---|']
for p in sorted((root/'src/NextgenComponents.Blazor').glob('Ng*.razor')):
 n=p.stem;d=D[n];source=p.read_text();fp,fs=flutter[n]
 lines=[f'# {n} — {d["title"]}','', '[Оглавление](README.md) · [Подключение](getting-started.md) · [Модели](models.md)','', '## Когда использовать','',d['use'],'','## Поведение и практические правила','',d['notes'],'','## Blazor: рабочий пример','','```razor',d['blazor'],'```','','## Flutter: рабочий пример','','```dart',d['dart'],'```','','## Параметры и события Blazor','','Имена чувствительны к регистру. `?` в типе разрешает null. Параметры с `EditorRequired` отмечены как обязательные; остальные имеют значение по умолчанию CLR или инициализатор ниже.','','| Параметр | Тип | По умолчанию / требование | Назначение |','|---|---|---|---|']
 for m in re.finditer(r'\[Parameter([^\]]*)\]\s*public\s+([^\n{}]+?)\s+(\w+)\s*\{\s*get;\s*set;\s*\}\s*(?:=\s*([^;]+);)?',source):
  attrs,typ,name,default=m.groups();lines.append(f'| `{name}` | `{md(typ)}` | {md("обязательный" if "EditorRequired" in attrs else default or ("false" if typ=="bool" else "0" if typ in ["int","double","decimal"] else "не задан"))} | {help.get(name.lower(),"Смотрите поведение и тип модели выше.")} |')
 inherited=re.search(r'@inherits InputBase<(.+)>',source)
 if inherited:
  typ=inherited[1];lines.extend([f'| `Value` | `{typ}` | значение модели | Текущее значение поля. |',f'| `ValueChanged` | `EventCallback<{typ}>` | — | Изменение значения. |',f'| `ValueExpression` | `Expression<Func<{typ}>>` | обязательно | Автоматически создаётся @bind-Value; при ручной привязке передайте явно. |','| `AdditionalAttributes` | словарь HTML-атрибутов | null | Дополнительные HTML/ARIA атрибуты поля. |'])
 lines+=['','## Параметры и события Flutter','','`required` в конструкторе означает обязательный аргумент, даже если его тип допускает null. `key` — стандартный Flutter Key. Значения по умолчанию приведены в точной сигнатуре ниже.','','| Аргумент | Тип | Назначение |','|---|---|---|']
 for m in re.finditer(r'final\s+(.+?)\s+(\w+(?:,\s*\w+)*)\s*;',fs,re.S):
  typ,names=m.groups()
  for name in re.split(r',\s*',names):lines.append(f'| `{name}` | `{md(typ.strip())}` | {help.get(name.lower(),"Смотрите поведение и тип модели выше.")} |')
 ctor=re.search(r'(?:const )?'+n+r'\(\{.*?\}\);',fs,re.S)
 lines+=['','```dart',ctor[0] if ctor else '// См. исходный код ниже.','```','','## Интеграция и диагностика','','Если интерфейс не обновляется, проверьте, сохраняет ли родитель результат callback и передаёт ли новое значение обратно. Для Blazor нужен интерактивный render mode; для Flutter — setState или используемый менеджер состояния. Данные формы отправляйте только после её успешной валидации.','','Проверяйте понятную подпись, пустое состояние, недоступность и размер контейнера. Клавиатурные возможности не означают полной сертификации screen reader. Сейчас проверяется Web в Chrome; нативные мобильные платформы будут проверяться отдельно.','','## Исходники и полный сценарий','',f'- [Blazor]({"../../"+str(p.relative_to(root))})',f'- [Flutter]({"../../"+str(fp.relative_to(root))})','- [Галереи и запуск](../../README.md#run)','- [Матрица возможностей](../catalog.md)','','Версия параметров сгенерирована из текущего исходного кода. Примеры и правила сопровождаются отдельно в `scripts/manual_content.py`; после изменения API выполните `python3 scripts/generate_manual.py`.','']
 (out/(n+'.md')).write_text('\n'.join(lines));index.append(f'| [{n}]({n}.md) | {d["title"]} |')
assert set(D)=={p.stem for p in (root/'src/NextgenComponents.Blazor').glob('Ng*.razor')}, "Every public component needs curated manual content"
(out/'README.md').write_text('\n'.join(index)+'\n')
print(f'Generated {len(D)} component manuals')
